import { useLayoutEffect, useRef, Suspense, type ReactNode, type CSSProperties } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { log } from "@/shared/lib/core/log";

export function KeptMountedPage({
  active,
  gate = true,
  keepAlive = false,
  fallback,
  style,
  children,
  label,
}: {
  active: boolean;
  gate?: boolean;
  keepAlive?: boolean;
  fallback?: ReactNode;
  style?: CSSProperties;
  children: ReactNode;
  /** Tags `[perf] keptMounted:<label> unhide took <n>ms`, read with `bsc perf phases` — the real-app
   *  counterpart of `request-177-components-graph-real-app-instrumentation`'s e2e harness, which can
   *  only ever measure a synthetic shell. Omit to stay silent (most callers do not need this). */
  label?: string;
}) {
  const everShown = useRef(false);
  const wasActive = useRef(active);
  // Snapshotted BEFORE this render's mutation below, so the FIRST activation (a mount, not an
  // un-hide) reads false here even though `everShown.current` is about to become true this render.
  const hadShownBefore = everShown.current;
  if (active && gate) everShown.current = true;
  const showing = gate && (everShown.current || keepAlive);

  // `useLayoutEffect` fires synchronously right after React commits the `display:none -> flex` flip
  // below, but before the browser paints — so timing from here through two animation frames captures
  // exactly the forced style/layout/paint cost `display:none` defers, measured on the app's REAL tree
  // rather than the synthetic shell `e2e/visitProfile.spec.ts` is limited to
  // (`request-177-components-graph-real-app-instrumentation`).
  useLayoutEffect(() => {
    const cameBack = active && !wasActive.current && hadShownBefore;
    wasActive.current = active;
    if (!cameBack || !label) return;
    const t0 = performance.now();
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        const ms = performance.now() - t0;
        log.warn(`[perf] keptMounted:${label} unhide took ${Math.round(ms)}ms`);
      });
    });
  }, [active, label, hadShownBefore]);

  if (!showing) return null;

  const body = fallback !== undefined ? <Suspense fallback={fallback}>{children}</Suspense> : children;
  return (
    <Box style={{ display: active ? "flex" : "none", flex: 1, flexDirection: "column", minHeight: 0, minWidth: 0, ...style }}>
      {body}
    </Box>
  );
}

