// KeptMountedPage (#2827) — the lazy-mount + kept-mounted (CSS-hidden) idiom. These tests pin the
// exact contract the docked-session Planner tabs depend on (Planning, Designs, and Algorithms): a page
// mounts on first activation, then STAYS mounted (toggled with `display`) when it goes inactive, so its
// live PTY survives a tab switch instead of being torn down — the Algorithms Librarian regression (#2827).
import { describe, it, expect, vi, beforeAll, beforeEach } from "vitest";
import { render } from "@testing-library/react";
vi.mock("@/shared/lib/core/log", () => ({ log: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() } }));
import { log } from "@/shared/lib/core/log";
import { KeptMountedPage } from "./KeptMountedPage";

describe("KeptMountedPage", () => {
  beforeAll(() => {
    vi.stubGlobal("requestAnimationFrame", (cb: FrameRequestCallback) => { cb(0); return 0; });
  });
  beforeEach(() => { vi.mocked(log.warn).mockClear(); });

  it("does not mount its children until first activated", () => {
    const { queryByTestId } = render(
      <KeptMountedPage active={false}><div data-testid="child" /></KeptMountedPage>,
    );
    expect(queryByTestId("child")).toBeNull();
  });

  it("keeps children MOUNTED (hidden) after going inactive — the PTY-survival contract", () => {
    // First activation latches the page; a later inactive render must keep it in the DOM (display:none),
    // NOT unmount it — unmounting is what killed + relaunched the Algorithms Librarian session (#2827).
    const { queryByTestId, rerender, container } = render(
      <KeptMountedPage active={true}><div data-testid="child" /></KeptMountedPage>,
    );
    expect(queryByTestId("child")).not.toBeNull();
    expect((container.firstElementChild as HTMLElement).style.display).toBe("flex");

    rerender(<KeptMountedPage active={false}><div data-testid="child" /></KeptMountedPage>);
    // Still in the DOM (the session survives), just hidden.
    expect(queryByTestId("child")).not.toBeNull();
    expect((container.firstElementChild as HTMLElement).style.display).toBe("none");
  });

  it("unmounts when the single-owner gate drops (tear-off), even once shown", () => {
    // The tear-off release: while the gate is false the page never latches and unmounts if already
    // shown, so the detached window becomes the SOLE owner of the single PTY (no double pty_create).
    const { queryByTestId, rerender } = render(
      <KeptMountedPage active={true} gate={true}><div data-testid="child" /></KeptMountedPage>,
    );
    expect(queryByTestId("child")).not.toBeNull();

    rerender(<KeptMountedPage active={true} gate={false}><div data-testid="child" /></KeptMountedPage>);
    expect(queryByTestId("child")).toBeNull();
  });

  it("keepAlive mounts the page HIDDEN even if it was never actively shown (#2940)", () => {
    // The studio-network reachability hook: a commission brings the target studio up (mounted, but not
    // the active view) so the pump can inject into its session.
    const { queryByTestId, container } = render(
      <KeptMountedPage active={false} keepAlive={true}><div data-testid="child" /></KeptMountedPage>,
    );
    expect(queryByTestId("child")).not.toBeNull();
    expect((container.firstElementChild as HTMLElement).style.display).toBe("none");
  });

  it("a keepAlive-only page UNMOUNTS when keepAlive drops — the on-demand teardown (#2940)", () => {
    // Never actively shown → not latched → when the commission clears (keepAlive false) the page
    // unmounts and releases its PTY. This is what keeps idle cost at zero.
    const { queryByTestId, rerender } = render(
      <KeptMountedPage active={false} keepAlive={true}><div data-testid="child" /></KeptMountedPage>,
    );
    expect(queryByTestId("child")).not.toBeNull();
    rerender(<KeptMountedPage active={false} keepAlive={false}><div data-testid="child" /></KeptMountedPage>);
    expect(queryByTestId("child")).toBeNull();
  });

  it("a page shown normally STAYS mounted after keepAlive drops (the normal latch wins, #2940)", () => {
    // If the user actually opened the studio, it must survive a commission ending — only the
    // commission-ONLY case tears down.
    const { queryByTestId, rerender, container } = render(
      <KeptMountedPage active={true} keepAlive={true}><div data-testid="child" /></KeptMountedPage>,
    );
    rerender(<KeptMountedPage active={false} keepAlive={false}><div data-testid="child" /></KeptMountedPage>);
    expect(queryByTestId("child")).not.toBeNull();
    expect((container.firstElementChild as HTMLElement).style.display).toBe("none");
  });

  it("times a real un-hide (request-177) — silent on the first show, logged on the way back", () => {
    // The FIRST activation is a mount, not an un-hide — `e2e/visitProfile.spec.ts` is the harness
    // that already distinguishes the two on a synthetic shell; this pins the same distinction on
    // the real KeptMountedPage.
    const { rerender } = render(
      <KeptMountedPage active={true} label="components"><div data-testid="child" /></KeptMountedPage>,
    );
    expect(log.warn).not.toHaveBeenCalled();

    // Going inactive (hidden) must not log either — only the RETURN is an un-hide.
    rerender(<KeptMountedPage active={false} label="components"><div data-testid="child" /></KeptMountedPage>);
    expect(log.warn).not.toHaveBeenCalled();

    rerender(<KeptMountedPage active={true} label="components"><div data-testid="child" /></KeptMountedPage>);
    expect(log.warn).toHaveBeenCalledWith(expect.stringMatching(/^\[perf\] keptMounted:components unhide took \d+ms$/));
  });

  it("stays silent across an un-hide when no label is given (most callers)", () => {
    const { rerender } = render(
      <KeptMountedPage active={true}><div data-testid="child" /></KeptMountedPage>,
    );
    rerender(<KeptMountedPage active={false}><div data-testid="child" /></KeptMountedPage>);
    rerender(<KeptMountedPage active={true}><div data-testid="child" /></KeptMountedPage>);
    expect(log.warn).not.toHaveBeenCalled();
  });
});
